/**
 * frontend/src/components/Dashboard.jsx
 * Version Ultra Premium - Design Unique 2026
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  red: '#FF0033',
  blue: '#0066FF',
  green: '#00FFAA',
  dark: '#0A0A0F',
  dark2: '#12121A',
  light: '#F8F9FF',
  text: '#E0E0E8',
  textMuted: '#A0A0B0',
  glass: 'rgba(18, 18, 26, 0.75)',
  border: 'rgba(255,255,255,0.08)',
};

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: { unique_students: 0, total_records: 0, avg_confidence: 0, max_confidence: 0, min_confidence: 0 }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [showAll, setShowAll] = useState(false);

  // ====================== CHARGEMENT DES DONNÉES ======================
  const loadData = async () => {
    try {
      setError(null);
      setLoading(true);

      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      if (!studentStatsRes?.success) throw new Error(studentStatsRes?.error || "Erreur stats étudiants");
      if (!attendanceStatsRes?.success) throw new Error(attendanceStatsRes?.error || "Erreur stats présence");
      if (!logRes?.success) throw new Error(logRes?.error || "Erreur journal");
      if (!statusRes?.success) throw new Error(statusRes?.error || "Erreur statut");

      const sData = studentStatsRes.data || {};
      const active = Number(sData.active_students) || 0;
      const logs = Array.isArray(logRes.data?.records) ? logRes.data.records : [];
      const presentToday = new Set(logs.map(r => r.student_id || r.id)).size;

      setStats({
        active_students: active,
        present_today: presentToday,
        absent_today: Math.max(0, active - presentToday),
        summary: attendanceStatsRes.data || {}
      });

      setAttendanceLog(logs);
      setStatusList(Array.isArray(statusRes.data?.students) ? statusRes.data.students : []);
      setLastUpdated(new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));

      setLoading(false);
    } catch (err) {
      setLoading(false);
      const errorMessage = err.message || 'Erreur de connexion';
      setError(errorMessage);
      addNotification?.('Erreur lors du chargement du dashboard', 'error');
    }
  };

  const handleRefresh = () => {
    setRefreshing(true);
    setTimeout(async () => {
      await loadData();
      setRefreshing(false);
    }, 1800);
  };

  useEffect(() => {
    loadData();
  }, []);

  if (loading) {
    return (
      <div style={styles.loadingScreen}>
        <div style={styles.loader}>Chargement du tableau de bord...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <h2 style={styles.errorTitle}>Erreur de synchronisation</h2>
          <p style={styles.errorText}>{error}</p>
          <button onClick={handleRefresh} style={styles.retryBtn} disabled={refreshing}>
            {refreshing ? 'Rafraîchissement...' : 'Réessayer maintenant'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* HEADER PREMIUM */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>Tableau de Bord</h1>
          <p style={styles.subtitle}>
            Surveillance des présences en temps réel • Mis à jour à {lastUpdated}
          </p>
        </div>
        <button 
          onClick={handleRefresh} 
          style={styles.refreshBtn}
          disabled={refreshing}
        >
          {refreshing ? 'Actualisation...' : 'Actualiser les données'}
        </button>
      </div>

      {/* STATISTIQUES - Design Glass + Gradient */}
      <div style={styles.statsGrid}>
        <StatCard 
          label="Étudiants inscrits" 
          value={stats.active_students} 
          color={COLORS.blue}
          accent="#0066FF"
        />
        <StatCard 
          label="Présents aujourd’hui" 
          value={stats.present_today} 
          color={COLORS.green}
          accent="#00FFAA"
        />
        <StatCard 
          label="Absents aujourd’hui" 
          value={stats.absent_today} 
          color={COLORS.red}
          accent="#FF0033"
        />
        <StatCard 
          label="Taux de présence" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : '—'} 
          color={
            stats.active_students > 0 && (stats.present_today / stats.active_students) >= 0.8 
              ? COLORS.green : COLORS.red
          }
          accent="#00FFAA"
        />
      </div>

      <div style={styles.mainGrid}>
        {/* DERNIERS SCANS */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Derniers scans aujourd’hui</h3>

          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>Aucune présence enregistrée aujourd’hui.</div>
          ) : (
            <div style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Confiance</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, showAll ? undefined : 10).map((record, index) => (
                <div key={index} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 600 }}>{record.student || record.name || 'Inconnu'}</div>
                  <div style={{ flex: 1 }}>
                    <ConfidenceBadge confidence={record.confidence} />
                  </div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>
                    {record.timestamp 
                      ? new Date(record.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) 
                      : '—'}
                  </div>
                </div>
              ))}
            </div>
          )}

          <div style={styles.tableFooter}>
            <span>Total aujourd’hui : <strong>{attendanceLog.length}</strong> scans</span>
            {attendanceLog.length > 10 && (
              <button onClick={() => setShowAll(!showAll)} style={styles.viewMoreBtn}>
                {showAll ? "Voir moins" : "Voir tous les scans"}
              </button>
            )}
          </div>
        </div>

        {/* ANALYSE DU PIPELINE */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Analyse du pipeline</h3>
          <div style={styles.summaryGrid}>
            <SummaryItem label="Total scans" value={stats.summary?.total_records || 0} color={COLORS.blue} />
            <SummaryItem label="Précision moyenne" value={stats.summary?.avg_confidence ? `${(stats.summary.avg_confidence * 100).toFixed(1)}%` : '—'} color={COLORS.green} />
            <SummaryItem label="Meilleure précision" value={stats.summary?.max_confidence ? `${(stats.summary.max_confidence * 100).toFixed(1)}%` : '—'} color={COLORS.green} />
            <SummaryItem label="Précision minimale" value={stats.summary?.min_confidence ? `${(stats.summary.min_confidence * 100).toFixed(1)}%` : '—'} color={COLORS.red} />
          </div>
        </div>
      </div>

      {/* LISTE DES ÉTUDIANTS */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Liste des étudiants</h3>
        {statusList.length === 0 ? (
          <div style={styles.emptyState}>Aucun étudiant trouvé.</div>
        ) : (
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Statut</div>
            </div>
            {statusList.map((student, index) => (
              <div key={index} style={styles.tableRow}>
                <div style={{ flex: 2, fontWeight: 600 }}>{student.name || 'Inconnu'}</div>
                <div style={{ flex: 2, color: COLORS.textMuted }}>{student.email || '—'}</div>
                <div style={{ flex: 1 }}>
                  <StatusBadge present={student.present} />
                </div>
              </div>
            ))}
          </div>
        )}
        <div style={styles.tableFooter}>
          Total : <strong>{statusList.length}</strong> étudiants • 
          <strong style={{ color: COLORS.green }}> {statusList.filter(s => s.present).length} présents</strong>
        </div>
      </div>
    </div>
  );
};

// ==================== SOUS-COMPOSANTS ====================

const StatCard = ({ label, value, color, accent }) => (
  <div style={{
    ...styles.statCard,
    background: `linear-gradient(145deg, ${COLORS.dark2}, ${COLORS.dark})`,
    border: `1px solid rgba(255,255,255,0.06)`,
    position: 'relative',
    overflow: 'hidden'
  }}>
    <div style={{
      position: 'absolute',
      top: '-20px',
      right: '-20px',
      width: '90px',
      height: '90px',
      background: `radial-gradient(circle, ${accent}22 0%, transparent 70%)`,
      borderRadius: '50%'
    }} />

    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  const score = Number(confidence) || 0;
  const perc = (score * 100).toFixed(0);
  let color = COLORS.red;
  let bg = 'rgba(255, 0, 51, 0.15)';

  if (score > 0.75) { color = COLORS.green; bg = 'rgba(0, 255, 170, 0.15)'; }
  else if (score > 0.45) { color = '#FFAA00'; bg = 'rgba(255, 170, 0, 0.15)'; }

  return (
    <span style={{
      padding: '6px 14px',
      backgroundColor: bg,
      color: color,
      borderRadius: '9999px',
      fontSize: '0.82rem',
      fontWeight: 700,
      border: `1px solid ${color}33`
    }}>
      {perc}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{
    padding: '7px 18px',
    backgroundColor: present ? 'rgba(0, 255, 170, 0.15)' : 'rgba(255, 0, 51, 0.15)',
    color: present ? COLORS.green : COLORS.red,
    borderRadius: '9999px',
    fontSize: '0.83rem',
    fontWeight: 700,
    border: present ? `1px solid ${COLORS.green}44` : `1px solid ${COLORS.red}44`
  }}>
    {present ? 'PRÉSENT' : 'ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
